// packages/core/src/routing/metaTools.ts
const SERVER_LIST_CAP = 40;

export function metaTools(scope: ResolvedScope, catalog: Catalog, mode: SearchMode): Tool[] {
  const names = catalog.serverNames(scope.serverIds);          // sorted, stable
  const shown = names.slice(0, SERVER_LIST_CAP).join(', ')
    + (names.length > SERVER_LIST_CAP ? ` (+${names.length - SERVER_LIST_CAP} more)` : '');
  const lexNote = mode === 'lexical'
    ? ' Matching is keyword-based (no embedding provider is configured on this gateway), so use'
    + ' concrete nouns and verbs from the tool\'s own domain rather than abstract phrasing, and'
    + ' retry with different keywords if nothing matches.'
    : '';
  return [{
    name: 'search_tools',
    description:
      'Find tools by describing the task you want to perform. This gateway fronts multiple MCP'
    + ' servers and does not list their tools directly — search first, then call. Returns ranked'
    + ' matches, each with a qualified name, a description and the token size of its input schema.'
    + ' Schemas are omitted unless tiny; pass every name you are considering to describe_tool in ONE'
    + ` call to get them, then invoke with call_tool. Servers in scope: ${shown}.` + lexNote,
    inputSchema: {
      type: 'object',
      properties: {
        query:   { type: 'string', maxLength: 512, description: 'What you want to do, in plain language. Include the domain noun (repository, invoice, cluster) and the verb (create, list, delete).' },
        limit:   { type: 'integer', minimum: 1, maximum: 25, default: 10 },
        servers: { type: 'array', items: { type: 'string' }, description: 'Optional: restrict to these server names.' },
      }, required: ['query'],
    },
    outputSchema: SEARCH_OUTPUT_SCHEMA,
  }, {
    name: 'describe_tool',
    description:
      'Return the full input schemas for tools found by search_tools. Pass every tool you are'
    + ' considering in one call. Names that are unknown or not available here are reported in'
    + ' `notFound` rather than failing the call.',
    inputSchema: {
      type: 'object',
      properties: { names: { type: 'array', items: { type: 'string' }, minItems: 1, maxItems: 20,
        description: 'Qualified tool names exactly as returned by search_tools.' } },
      required: ['names'],
    },
  }, {
    name: 'call_tool',
    description:
      'Invoke a tool found via search_tools, by its qualified name. `arguments` must match that'
    + ' tool\'s inputSchema exactly — call describe_tool first unless search_tools already'
    + ' returned the schema inline.',
    inputSchema: {
      type: 'object',
      properties: {
        name:      { type: 'string', description: 'Qualified tool name from search_tools.' },
        arguments: { type: 'object', additionalProperties: true, description: 'Arguments matching that tool\'s inputSchema.' },
      }, required: ['name'],
    },
  }];
}

// packages/core/src/routing/dispatch.ts  — NO http, NO session, NO request object
export type ResolvedScope = {            // CONTRACT: owned by scope resolution, built in packages/server
  kind: 'all' | 'group' | 'server';
  groupId?: string;
  serverIds: string[];                   // already authz-filtered; never from caller arguments
  allowedQualifiedNames: string[] | null;// group per-server item selection; null = all
  smart: boolean;
};

export interface SmartRouterDeps {
  search: Search;
  catalog: Catalog;
  callTool(scope: ResolvedScope, principal: Principal, name: string, args: unknown): Promise<CallToolResult>;
}

export function smartListTools(scope: ResolvedScope, catalog: Catalog, mode: SearchMode): Tool[];

export async function smartCallTool(
  d: SmartRouterDeps, scope: ResolvedScope, principal: Principal,
  name: string, args: unknown,
): Promise<CallToolResult> {
  switch (name) {
    case 'search_tools': {
      const a = SearchArgs.parse(args);                       // zod 4.6.5, throws -32602
      return json(await d.search.run(scope, a));
    }
    case 'describe_tool': {
      const a = DescribeArgs.parse(args);
      return json(d.catalog.describeInScope(scope, a.names));  // {tools:[...], notFound:[...]}
    }
    case 'call_tool': {
      const a = CallArgs.parse(args);
      // re-entry with smart:false: meta-tool names become unroutable by construction,
      // and enable/disable is enforced by the SAME code as a direct call.
      return d.callTool({ ...scope, smart: false }, principal, a.name, a.arguments ?? {});
    }
    default:
      throw new ToolUnavailableError(name);  // identical text to a nonexistent tool
  }
}

