// packages/core/src/routing/search.ts
export type SearchMode = 'semantic' | 'lexical';
export const SearchArgs = z.object({
  query: z.string().trim().min(1).max(512),
  limit: z.number().int().min(1).max(25).default(10),
  servers: z.array(z.string().max(128)).max(50).optional(),
});
export type SearchHit = {
  name: string;            // qualified <server><sep><tool> — pass this to call_tool verbatim
  server: string;
  description: string;     // truncated to 300 chars
  score: number;           // fused, 3dp
  schemaTokens: number;
  inputSchema?: unknown;   // present iff schemaTokens <= 50
};
export type SearchResponse = { mode: SearchMode; hits: SearchHit[]; searched: number };

export interface Search { run(scope: ResolvedScope, q: z.infer<typeof SearchArgs>): Promise<SearchResponse>; }
export function createSearch(db: Db, embedder: () => Embedder | null, catalog: Catalog): Search;

