// packages/core/src/db/schema/routing.ts  (path owned by the storage subsystem)
export const toolEmbedding = pgTable('tool_embedding', {
  id:            uuid('id').primaryKey().defaultRandom(),
  serverId:      uuid('server_id').notNull().references(() => server.id, { onDelete: 'cascade' }),
  serverName:    text('server_name').notNull(),
  toolName:      text('tool_name').notNull(),
  qualifiedName: text('qualified_name').notNull(),
  enabled:       boolean('enabled').notNull().default(true),
  searchText:    text('search_text').notNull(),
  contentHash:   text('content_hash').notNull(),
  modelId:       text('model_id'),
  embedding:     vector('embedding', { dimensions: 1536 }),
  schemaTokens:  integer('schema_tokens').notNull().default(0),
  updatedAt:     timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
}, t => [ unique('tool_embedding_key').on(t.serverId, t.toolName) ]);

