// packages/core/src/routing/embedText.ts
const SPLIT = (s: string) => s.replace(/([a-z0-9])([A-Z])/g, '$1 $2').replace(/[_\-.]+/g, ' ');

export function searchText(t: CachedTool, serverDescription: string): string {
  const props = Object.entries((t.tool.inputSchema as any)?.properties ?? {})
    .slice(0, 30)
    .map(([k, v]: [string, any]) => `${SPLIT(k)} ${String(v?.description ?? '').slice(0, 120)}`)
    .join(' ');
  return [
    `${t.serverName} ${SPLIT(t.toolName)}`,
    serverDescription.slice(0, 160),
    t.tool.description ?? '',
    props,
  ].join('\n').replace(/\s+/g, ' ').trim().slice(0, 2000);
}
export const contentHash = (s: string) => createHash('sha256').update(s).digest('hex');

// packages/core/src/routing/provider.ts
export type EmbeddingConfig = {
  baseUrl: string;                        // OpenAI-compatible /v1/embeddings
  apiKey: string;
  apiKeyHeader?: 'Authorization' | 'api-key';  // 'api-key' for Azure OpenAI
  model: string;
  dimensions?: number;                    // passed through where the provider supports it
};
export type Embedder = {
  modelId: string;      // `${host}:${model}:${dims}` — the staleness key stored per row
  dims: number;         // MUST be <= 1536
  embed(texts: string[]): Promise<Float32Array[]>;   // <=100 per call, zero-padded to 1536
};
export function createEmbedder(cfg: EmbeddingConfig | null): Embedder | null;

// packages/core/src/routing/sync.ts
export type RoutingStatus = {
  mode: SearchMode; provider: string | null; model: string | null; dims: number | null;
  rows: number; embedded: number; stale: number; missing: number;
  lastSyncAt: string | null; lastError: string | null; syncing: boolean;
};
export interface Sync {
  start(): void;                                // startup full pass + subscribe to toolsChanged
  enqueue(serverId: string): void;              // debounced 2s, concurrency 1
  resyncAll(reason: 'model-changed' | 'manual'): void;
  setEnabled(serverId: string, toolName: string, enabled: boolean): Promise<void>; // same txn as the toggle
  status(): Promise<RoutingStatus>;
}
export function createSync(db: Db, catalog: Catalog, embedder: () => Embedder | null, log: Logger): Sync;

